// A disposable resource
class FileHandle {
  constructor(path) {
    this.path = path;
    console.log("Opened: " + path);
  }

  [Symbol.dispose]() {
    console.log("Closed: " + this.path);
  }
}

function processFile() {
  using file = new FileHandle("data.txt");
  console.log("Processing...");
  // file is automatically disposed when function ends!
}

processFile();
// Output:
// Opened: data.txt
// Processing...
// Closed: data.txt

// Create a ZonedDateTime
let now = Temporal.Now.zonedDateTime();
console.log(now.toString());
// 2026-08-25T10:30:00+05:30[Asia/Kolkata]

// Add duration
let tomorrow = now.add({ days: 1 });
let nextWeek = now.add({ weeks: 1 });

// Timezone conversion
let tokyo = now.withTimeZone("Asia/Tokyo");
console.log(tokyo.hour);  // different hour!

// Plain date and time (no timezone)
let birthday = Temporal.PlainDate.from("1995-06-15");
let time = Temporal.PlainTime.from("14:30:00");

// Duration
let duration = Temporal.Duration.from({ hours: 1, minutes: 30 });
let later = now.add(duration);
